const host=document.getElementById('replay-content');
const titles={hunger:'饥饿驱动 H',stress:'紧张 S',exploration:'探索倾向 E',fatigue:'疲劳 F'},modelNames={logistic:'LR 逻辑回归',gam:'GAM 加性模型',hmm:'HMM 隐马尔可夫'};
const labelNames={high:'高',low:'低',unknown:'无法判断'};
const featureNames={speed_mean:['平均游速','体长/秒'],acceleration_mean:['平均加速度','体长/秒²'],displacement_ratio:['位移 / 路径',''],turn_rate:['转向率','弧度/秒'],feeding_zone_fraction:['投喂区占比','比例'],surface_fraction:['表层占比','比例'],dispersion:['群体分散',''],activity_fraction:['活动占比','比例'],wall_fraction:['靠壁占比','比例'],shelter_fraction:['可见遮蔽区占比','比例'],speed_baseline_z:['游速历史偏离',''],feeding_baseline_z:['投喂区历史偏离','']};
const pct=v=>Number.isFinite(v)?`${(v*100).toFixed(1)}%`:'—';
function element(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
try{
const response=await fetch('./assets/model-replay.json');if(!response.ok)throw Error('无法读取实验文件');const data=await response.json();if(data.domain!=='synthetic'||data.kind!=='held_out_single_fish_replay')throw Error('实验数据类型不符');
host.innerHTML=`<div class="replay-toolbar"><label>测试场景 <select id="replay-session" aria-label="实验回放场景"></select></label><label>状态维度 <select id="replay-state" aria-label="实验回放状态维度"><option value="hunger">饥饿驱动 H</option><option value="stress">紧张 S</option><option value="exploration">探索倾向 E</option><option value="fatigue">疲劳 F</option></select></label><output id="replay-time"></output></div><div class="replay-timeline"><button id="replay-prev" aria-label="上一时间窗">←</button><input id="replay-window" aria-label="实验回放时间窗" type="range" min="0" max="11" value="0" step="1"><button id="replay-next" aria-label="下一时间窗">→</button></div><div class="replay-truth"><div><span>窗口隐藏真值</span><strong id="replay-truth-value"></strong><small id="replay-truth-label"></small></div><p>真值是生成器的窗口均值。模型输出的是“高类别”的概率，不能把二者当作同一种连续分数。</p></div><div id="replay-models" class="replay-models"></div><div id="replay-quality" class="replay-quality"></div><p id="replay-events" class="replay-events"></p><details class="replay-features"><summary>查看该窗口的 12 项模型输入</summary><div id="replay-features-grid"></div><p>缺失显示为“缺失”，不填成正常。短期历史不足或波动过小时，历史偏离保持缺失。</p></details><p class="replay-footnote">指标来自完整独立测试集；概率门槛为 0.70。包括质量不足的窗口在回放中保留；评估指标以源评估文件为准。所有结果仅验证合成实验，不代表真实鱼心理测量。</p>`;
const get=id=>document.getElementById(id),select=get('replay-session'),slider=get('replay-window');data.sessions.forEach(s=>{const o=element('option','',`${s.id} · H${s.initial_state.hunger>=.5?'高':'低'} S${s.initial_state.stress>=.5?'高':'低'} E${s.initial_state.exploration>=.5?'高':'低'} F${s.initial_state.fatigue>=.5?'高':'低'}`);o.value=s.id;select.append(o);});select.value='test_12';
function render(){const session=data.sessions.find(s=>s.id===select.value),index=Number(slider.value),w=session.windows[index],state=get('replay-state').value,task='sim_'+state;slider.max=String(session.windows.length-1);get('replay-time').textContent=`${w.start_s.toFixed(0)}–${w.end_s.toFixed(0)} 秒 · ${index+1}/${session.windows.length}`;get('replay-prev').disabled=index===0;get('replay-next').disabled=index===session.windows.length-1;get('replay-truth-value').textContent=w.truth[state].toFixed(3);get('replay-truth-label').textContent=`${titles[state]}：${w.truth[state]>=session.label_threshold?'高':'低'}（标签阈值 ${session.label_threshold}）`;
const models=get('replay-models');models.replaceChildren();for(const backend of data.backends){const pred=w.predictions[backend][task],metrics=data.metrics[backend][task],card=element('article','replay-model');card.append(element('h3','',modelNames[backend]));if(!pred){card.append(element('p','','该任务未训练'));models.append(card);continue;}const verdict=element('span',`replay-verdict ${pred.label==='unknown'?'unknown':''}`,labelNames[pred.label]??pred.label);card.append(verdict,element('p','probability-caption','P（高类别）'),element('strong','probability-value',pct(pred.probabilities?.high)));const meter=element('meter','probability-meter');meter.min=0;meter.max=1;meter.hidden=!Number.isFinite(pred.probabilities?.high);meter.value=pred.probabilities?.high??0;meter.setAttribute('aria-label',`${modelNames[backend]}的${titles[state]}高类别概率`);card.append(meter,element('p','prediction-reason',pred.reason||'观测质量与概率门槛通过'));const stats=element('div','replay-stats');stats.append(element('span','',`测试准确率 ${pct(metrics.accuracy)}`),element('span','',`接受率 ${pct(metrics.accepted_fraction)}`));card.append(stats);models.append(card);}
get('replay-quality').textContent=w.quality_ok?'观测质量：通过':`观测质量：不足 · ${w.quality_reasons.join('；')}`;get('replay-quality').classList.toggle('quality-warning',!w.quality_ok);
const eventNames={food_offered:'投放食物',disturbance:'模拟惊扰',food_consumed:'模拟进食'};const events=session.events.filter(e=>e.time_s>=w.start_s&&e.time_s<w.end_s);get('replay-events').textContent=events.length?'本窗口事件：'+events.map(e=>`${e.time_s.toFixed(1)} 秒 ${eventNames[e.type]||e.type}`).join(' · '):'本窗口无生成器事件';
const grid=get('replay-features-grid');grid.replaceChildren();for(const [key,[name,unit]] of Object.entries(featureNames)){const item=element('div','replay-feature'),v=w.features[key];item.append(element('span','',name),element('strong','',Number.isFinite(v)?(unit==='比例'?pct(v):`${v.toFixed(3)}${unit?' '+unit:''}`):'缺失'));grid.append(item);}}
select.onchange=()=>{slider.value='0';render();};get('replay-state').onchange=render;slider.oninput=render;get('replay-prev').onclick=()=>{slider.value=String(Math.max(0,Number(slider.value)-1));render();};get('replay-next').onclick=()=>{slider.value=String(Math.min(Number(slider.max),Number(slider.value)+1));render();};render();host.setAttribute('aria-busy','false');
}catch(error){host.replaceChildren(element('p','replay-error','实验回放暂不可用。请通过本地 HTTP 服务打开，并检查 assets/model-replay.json 是否存在。'));host.setAttribute('aria-busy','false');console.error('Replay data failed',error);}
